    }
    #[must_use]
    pub fn decisions(&self) -> &[Decision] {
        &self.decisions
    }
    #[must_use]
    pub const fn policy(&self) -> &Policy {
        &self.policy
    }
    #[must_use]
    pub const fn output(&self) -> &Output {
        &self.output
    }
}

impl State {
    #[must_use]
    pub fn text(&self) -> &str {
        &self.text
    }
    #[must_use]
    pub fn features(&self) -> &[String] {
        &self.features
    }
    #[must_use]
    pub fn memory(&self) -> &[Memory] {
        &self.memory
    }
}

impl Memory {
    #[must_use]
    pub fn id(&self) -> &str {
        &self.id
    }
    #[must_use]
    pub fn text(&self) -> &str {
        &self.text
    }
    #[must_use]
    pub fn tag(&self) -> &str {
        &self.tag
    }
    #[must_use]
    pub const fn age_turns(&self) -> u32 {
        self.age_turns
    }
}

impl Decision {
    #[must_use]
    pub fn kind(&self) -> &str {
        &self.kind
    }
    #[must_use]
    pub fn question(&self) -> &str {
        &self.question
    }
    #[must_use]
    pub fn labels(&self) -> &[String] {
        &self.labels
    }
    #[must_use]
    pub fn probs(&self) -> &[f64] {
        &self.probs
    }
    #[must_use]
    pub const fn selected(&self) -> usize {
        self.selected
    }
    #[must_use]
    pub fn selected_label(&self) -> &str {
        &self.labels[self.selected]
    }
    #[must_use]
    pub const fn confidence(&self) -> f64 {
        self.confidence
    }
    #[must_use]
    pub const fn margin(&self) -> f64 {
        self.margin
    }
    #[must_use]
    pub const fn calibration(&self) -> &Calibration {
        &self.calibration
    }
    #[must_use]
    pub const fn p(&self) -> Option<f64> {
        self.p
    }
    #[must_use]
    pub const fn expectation(&self) -> Option<f64> {
        self.expectation
    }
    /// Probability of a label by name, or `None` when the decision did not offer
    /// it. Policy reads a distribution this way; an index may be renumbered.
    #[must_use]
    pub fn prob_of(&self, label: &str) -> Option<f64> {
        self.labels.iter().position(|l| l == label).map(|i| self.probs[i])
    }
}

impl Calibration {
    #[must_use]
    pub fn method(&self) -> &str {
        &self.method
    }
    #[must_use]
    pub const fn temperature(&self) -> Option<f64> {
        self.t
    }
    #[must_use]
    pub fn is_calibrated(&self) -> bool {
        self.method != "none"
    }
}

impl Policy {
    #[must_use]
    pub fn rule(&self) -> &str {
        &self.rule
    }
    #[must_use]
    pub fn branch(&self) -> &str {
        &self.branch
    }
}

impl Output {
    #[must_use]
    pub fn table(&self) -> &str {
        &self.table
    }
    #[must_use]
    pub const fn index(&self) -> usize {
        self.index
    }
    #[must_use]
    pub fn text(&self) -> &str {
        &self.text
    }
}
