cd /Users/mike/github/sw-ml-study/demo-decision-model
python3 - <<'PY'
p = "crates/tdm-trace/src/lib.rs"
s = open(p).read()

# 1. Doc comment: explain slots
s = s.replace(
"""//! 2. **Output text must be quoted from a table the trace carries.** Every turn
//!    names a table and an index, and the text must be byte-identical to the
//!    entry found there. A trace whose output was not in its own table is
//!    rejected as [`ValidationError::TextNotInTable`]. This makes the "the model
//!    cannot invent an output" property checkable from the artifact alone,
//!    rather than only by the repository that produced it.""",
"""//! 2. **Output text must be reconstructible from a table the trace carries.**
//!    Every turn names a table and an index, and the text must equal that entry
//!    with its `{}` placeholders filled, in order, by the turn's recorded slots.
//!    An entry with no placeholder must match byte for byte. A trace whose
//!    output cannot be rebuilt this way is rejected as
//!    [`ValidationError::TextNotInTable`].
//!
//!    Slots exist because a canned frame is not always a whole sentence: an
//!    application may splice quoted input back into it ("Earlier you said that
//!    {}."). That is still not generation — the frame is a fixed literal and the
//!    slot is text the program already had — but pretending the output were
//!    byte-identical to a table entry would be a claim the format could not
//!    honestly make. Rebuilding it exactly is the claim that holds.""")

# 2. Output struct gains slots
s = s.replace("""pub struct Output {
    table: String,
    index: usize,
    text: String,
}""",
"""pub struct Output {
    table: String,
    index: usize,
    text: String,
    /// Values spliced into the entry's `{}` placeholders, in order.
    #[serde(default)]
    slots: Vec<String>,
}""")

# 3. Error variant
s = s.replace("""    /// The output text was not byte-identical to the table entry it cited.
    /// This is the invariant that makes the no-generation claim checkable.
    TextNotInTable(u32),""",
"""    /// The turn supplied a different number of slots than the entry has
    /// placeholders.
    SlotCount(u32),
    /// The output text could not be rebuilt from the table entry it cited and
    /// the slots it recorded. This is the invariant that makes the
    /// no-generation claim checkable from the artifact alone.
    TextNotInTable(u32),""")

# 4. validate_output
s = s.replace("""    /// The no-generation invariant: a turn's text must be quoted verbatim from a
    /// table the trace itself carries.
    fn validate_output(&self, turn: &Turn) -> Result<(), ValidationError> {
        let Some(table) = self.table(&turn.output.table) else {
            return Err(ValidationError::UnknownTable(turn.output.table.clone()));
        };
        let Some(entry) = table.entries.get(turn.output.index) else {
            return Err(ValidationError::IndexOutOfTable(turn.index));
        };
        if entry.as_bytes() != turn.output.text.as_bytes() {
            return Err(ValidationError::TextNotInTable(turn.index));
        }
        Ok(())
    }""",
"""    /// The no-generation invariant: a turn's text must be rebuildable from an
    /// entry of a table the trace itself carries, plus the slots it recorded.
    fn validate_output(&self, turn: &Turn) -> Result<(), ValidationError> {
        let Some(table) = self.table(&turn.output.table) else {
            return Err(ValidationError::UnknownTable(turn.output.table.clone()));
        };
        let Some(entry) = table.entries.get(turn.output.index) else {
            return Err(ValidationError::IndexOutOfTable(turn.index));
        };
        for slot in &turn.output.slots {
            bounded_text(slot, "output slot")?;
        }
        if entry.matches(PLACEHOLDER).count() != turn.output.slots.len() {
            return Err(ValidationError::SlotCount(turn.index));
        }
        if render(entry, &turn.output.slots).as_bytes() != turn.output.text.as_bytes() {
            return Err(ValidationError::TextNotInTable(turn.index));
        }
        Ok(())
    }""")

# 5. render helper + PLACEHOLDER const
s = s.replace("""/// Gap between the two largest probabilities; 1 for a single-label set.""",
"""/// Fills each `{}` in `entry` with the next slot, in order. The caller has
/// already checked that the counts agree.
fn render(entry: &str, slots: &[String]) -> String {
    let mut out = String::with_capacity(entry.len());
    let mut slots = slots.iter();
    let mut rest = entry;
    while let Some(at) = rest.find(PLACEHOLDER) {
        out.push_str(&rest[..at]);
        if let Some(slot) = slots.next() {
            out.push_str(slot);
        }
        rest = &rest[at + PLACEHOLDER.len()..];
    }
    out.push_str(rest);
    out
}

/// Gap between the two largest probabilities; 1 for a single-label set.""")

s = s.replace("""/// Absolute tolerance for a probability sum and for every derived scalar.
const TOLERANCE: f64 = 1e-6;""",
"""/// Absolute tolerance for a probability sum and for every derived scalar.
const TOLERANCE: f64 = 1e-6;

/// The placeholder a table entry uses to mark a spliced slot.
const PLACEHOLDER: &str = "{}";""")

# 6. accessor
s = s.replace("""    #[must_use]
    pub fn text(&self) -> &str {
        &self.text
    }
}""",
"""    #[must_use]
    pub fn text(&self) -> &str {
        &self.text
    }
    #[must_use]
    pub fn slots(&self) -> &[String] {
        &self.slots
    }
}""", 1) if s.count("""    #[must_use]
    pub fn text(&self) -> &str {
        &self.text
    }
}""") == 1 else s

open(p, "w").write(s)
