                if *tracing {
                    <Trace bundle={bundle.clone()} shown={shown} />
                }
            </main>
            <footer>
                <p>
                    { format!("Runs entirely in your browser: {} parameters, trained from random initialization in sw-MLPL. ",
                        bundle.param_count()) }
                    { "This is a thin slice: one uncalibrated Choice, so confidences near 1.00 are not probabilities yet." }
                </p>
                <p>
                    { "Copyright (c) 2026 Michael A Wright · MIT License · " }
                    <a href="https://github.com/sw-ml-study/demo-decision-model">{ "source" }</a>
                </p>
            </footer>
        </div>
    }
}
