            b.labels[best].clone()
        } else {
            abstained += 1;
            "ABSTAIN".to_owned()
        };
        if after != b.labels[before.selected] {
            changed += 1;
            println!("{line:<34} {:<8} {:.2} -> {after:<8} [{}]", b.labels[before.selected], before.confidence, tokens.join(" "));
