ex_n = list_len(ex_all);

ex_trf = u:cm_featurize(ex_tr.texts, ex_slots, ex_width);
ex_vaf = u:cm_featurize(ex_va.texts, ex_slots, ex_width);
ex_wif = u:cm_featurize(ex_wi.texts, ex_slots, ex_width);
ex_prf = u:cm_featurize(ex_probe, ex_slots, ex_width);
ex_alf = u:cm_featurize(ex_all, ex_slots, ex_width);

cm_E = param[1024, 32];
cm_E = randn(11, [1024, 32]) * 0.1;
cm_W = param[32, 9];
cm_W = randn(12, [32, 9]) * 0.1;
cm_b = param[9];
cm_b = fill([9], 0);

ex_E = fill([0], 0);
ex_Wh = fill([0], 0);
ex_B = fill([0], 0);
ex_P = fill([0], 0);
ex_metrics = fill([0], 0);
ex_worst_rounding = 0;
ex_changed = 0;
ex_done = 0;
ex_ms = "";
