  ex_rw = {E: u:ex_round(cm_E), W: u:ex_round(cm_W), b: u:ex_round(cm_b)};
  ex_p_r = softmax(u:cm_infer(ex_rw, ex_alf.ids, ex_alf.wmask), 1);
  ex_p_o = softmax(u:cm_infer(ex_raw, ex_alf.ids, ex_alf.wmask), 1);
  ex_worst_rounding = reduce(:max, [ex_worst_rounding, reduce(:max, abs(ex_p_r - ex_p_o))]);
  ex_changed = ex_changed + reduce_add(1 - eq(argmax(ex_p_r, 1), argmax(ex_p_o, 1)));
  ex_E = concat(ex_E, reshape(ex_rw.E, [32768]));
  ex_Wh = concat(ex_Wh, reshape(ex_rw.W, [288]));
  ex_B = concat(ex_B, ex_rw.b);
  ex_P = concat(ex_P, reshape(ex_p_r, [ex_n * ex_k]));
  ex_metrics = concat(ex_metrics, [cross_entropy(u:cm_infer(ex_rw, ex_trf.ids, ex_trf.wmask), ex_tr.y), u:ex_acc(ex_rw, ex_trf, ex_tr.y), u:ex_acc(ex_rw, ex_vaf, ex_va.y), u:ex_acc(ex_rw, ex_wif, ex_wi.y), u:ex_conf(ex_rw, ex_vaf), u:ex_conf(ex_rw, ex_prf)]);
  print("snapshot", take(ex_nominal, 0, ex_c), "s  steps", ex_target, " loss", take(ex_metrics, 0, ex_c * 6), " val", take(ex_metrics, 0, ex_c * 6 + 2), " wild", take(ex_metrics, 0, ex_c * 6 + 3), " val conf", take(ex_metrics, 0, ex_c * 6 + 4), " probe conf", take(ex_metrics, 0, ex_c * 6 + 5));
  ex_c = ex_c + 1
};

ex_match = fill([0], 0);
ex_i = 0;
while lt(ex_i, ex_n) {
  ex_match = concat(ex_match, [u:ez_matcher(u:text_lg(ex_all, ex_i))]);
  ex_i = ex_i + 1
};

ex_bundle = {schema: "sw-ml-study.decision-bundle", version: 2, provenance: {producer: "demos/eliza/export.mlpl", producer_revision: "timeline-v1", generated_at: "2026-09-20", source_description: "demo 01 Choice model: one full-batch Adam run from seeded random initialization over 232 generated sentences, snapshotted after 0, 11, 22, 55 and 110 steps -- what 0, 1, 2, 5 and 10 seconds of training bought on an M1 Max with mlpl-repl 0.22.0. Weights rounded to 1e-4 for transport."}, demo: "demo 01", title: "ELIZA", question: "what should the reply be?", labels: str_split(u:ez_labels(), "|"), fallback: "FALLBACK", threshold: 0.4, slots: ex_slots, width: ex_width, dim: 32, snapshots: {steps: ex_steps, seconds: ex_nominal, metric_names: ["train loss", "train accuracy", "val accuracy", "wild accuracy", "val confidence", "probe confidence"], metrics: reshape(ex_metrics, [5, 6]), embedding: reshape(ex_E, [5, 32768]), head: reshape(ex_Wh, [5, 288]), bias: reshape(ex_B, [5, 9])}, default_snapshot: 4, responses: u:ex_per_label("responses"), keywords: u:ex_per_label("keywords"), match_order: u:ez_match_order(), examples: ex_transcript, parity: {inputs: ex_all, probs: reshape(ex_P, [5, ex_n * ex_k]), matcher: ex_match}};

ex_json = unwrap(to_json(ex_bundle));
ex_saved = write_atomic("fixtures/bundles/demo01.json", ex_json);
print("bundle written", ex_saved, "bytes", str_len(ex_json));
print("parity inputs", ex_n, "per snapshot; probe inputs", list_len(ex_probe));
print("training ms per segment:", ex_ms);
print("rounding to 1e-4 moved any parity probability by at most", ex_worst_rounding, "and changed", ex_changed, "decisions across all snapshots");
print("")
'''
open(p,"w").write(header + body)
