  w = {E: cm_E, W: cm_W, b: cm_b};
  pv = softmax(u:cm_infer(w, vaf.ids, vaf.wmask), 1);
  pp = softmax(u:cm_infer(w, prf.ids, prf.wmask), 1);
  okp = eq(argmax(pp, 1), pr.y);
  confp = reduce(:max, pp, 1);
  print(label, "val", mean(eq(argmax(pv, 1), va.y)), "probe", mean(okp), "conf-when-wrong", reduce_add(confp * (1 - okp)) / reduce_add(1 - okp), "conf-when-right", reduce_add(confp * okp) / reduce_add(okp));
  1
}
e0 = u:ev("step 0  ");
t0 = clock_ms();
l = u:cm_train_smooth(ids, wm, yy, 10, 0.05, 0.1);
print("10 steps ms", clock_ms() - t0);
e1 = u:ev("step 10 ");
l = u:cm_train_smooth(ids, wm, yy, 30, 0.05, 0.1);
e2 = u:ev("step 40 ");
l = u:cm_train_smooth(ids, wm, yy, 60, 0.05, 0.1);
e3 = u:ev("step 100");
print("")
EOF
