def u:cm_stack(a, b) {
  "Stack two arrays of any equal trailing shape along their first axis (concat joins only rank-1 arrays).";
  s = shape(a);
  rows = take(s, 0, 0) + take(shape(b), 0, 0);
  reshape(concat(reshape(a, [reduce_mul(s)]), reshape(b, [reduce_mul(shape(b))])), scatter(s, 0, rows))
}

def u:cm_stack_batches(a, b) {
  "Stack two featurized batches row-wise, keeping ids and pooling weights aligned.";
  {ids: u:cm_stack(a.ids, b.ids), wmask: u:cm_stack(a.wmask, b.wmask)}
}
