//! The featurizer, ported exactly from `lib/text.mlpl`: normalize, split into
//! words, then hash words and adjacent bigrams into a fixed number of slots.
//!
//! Exactness matters more than elegance here. A single character handled
//! differently changes a hash, which changes which embedding row is read, which
//! changes the decision. The parity test is what keeps this honest.

/// The rolling-hash modulus, as in MLPL.
const MODULUS: u64 = 2_147_483_647;

/// Lowercase ASCII letters, keep letters, digits and spaces, delete apostrophes,
/// and turn every other character into a space. Matches `u:text_clean`: both
/// delete straight and curly apostrophes, and both work character by character.
fn clean(s: &str) -> String {
    s.chars()
        .filter_map(|c| match c {
            'A'..='Z' => Some(c.to_ascii_lowercase()),
            'a'..='z' | '0'..='9' | ' ' => Some(c),
            '\'' | '\u{2018}' | '\u{2019}' => None,
            _ => Some(' '),
        })
        .collect()
}

/// The non-empty words of a cleaned string.
#[must_use]
pub fn words(s: &str) -> Vec<String> {
    clean(s)
        .split(' ')
        .filter(|w| !w.is_empty())
        .map(str::to_owned)
        .collect()
}

/// Base-31 rolling checksum of a string's bytes modulo 2147483647.
#[must_use]
pub fn hash(s: &str) -> u64 {
    s.bytes().fold(7, |h, b| (h * 31 + u64::from(b)) % MODULUS)
}

/// What the model sees for one input.
#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct Features {
    /// Embedding rows of the features the model has evidence about; these are
    /// the rows the mean pool reads.
    pub slots: Vec<usize>,
    /// Every feature, for display: words first, then `a_b` bigrams.
    pub tokens: Vec<String>,
    /// Per token, whether it contributes. Always true under hashing, which is
    /// exactly its flaw: an unseen token still reads some row.
    pub known: Vec<bool>,
}

/// The features' text, before any lookup: words first, then adjacent bigrams,
/// up to `width` in all.
#[must_use]
pub fn tokens(text: &str, width: usize) -> Vec<String> {
    let ws = words(text);
    let mut out: Vec<String> = ws.iter().take(width).cloned().collect();
    for pair in ws.windows(2) {
        if out.len() >= width {
            break;
        }
        out.push(format!("{}_{}", pair[0], pair[1]));
    }
    out
}

/// Features against an exact vocabulary: unknown tokens are kept for display
/// and contribute nothing.
#[must_use]
pub fn featurize_vocab(text: &str, width: usize, row: impl Fn(&str) -> Option<usize>) -> Features {
    let toks = tokens(text, width);
    let rows: Vec<Option<usize>> = toks.iter().map(|t| row(t)).collect();
    Features {
        slots: rows.iter().flatten().copied().collect(),
        known: rows.iter().map(Option::is_some).collect(),
        tokens: toks,
    }
}

/// Words first, then adjacent bigrams, up to `width` features in all.
#[must_use]
pub fn featurize(text: &str, slots: usize, width: usize) -> Features {
    let tokens = tokens(text, width);
    #[expect(
        clippy::cast_possible_truncation,
        reason = "a hash modulo a slot count below u32::MAX fits usize on every target"
    )]
    let ids = tokens

    /// The shared state: the mean of the embedding rows the known features
    /// address, or zeros when there are none.
    #[must_use]
    pub fn pooled(&self, features: &Features) -> Vec<f64> {
        let d = self.bundle.dim;
        let mut pooled = vec![0.0; d];
        if !features.slots.is_empty() {
            for &slot in &features.slots {
                for (j, p) in pooled.iter_mut().enumerate() {
                    *p += self.weights.embedding[slot * d + j];
                }
            }
            #[expect(
                clippy::cast_precision_loss,
                reason = "feature count is at most the width"
            )]
            let n = features.slots.len() as f64;
            for p in &mut pooled {
                *p /= n;
            }
        }
        pooled
    }

    /// Logits for one input. An input with no features pools to zero, so its
    /// logits are the bias alone, exactly as in MLPL.
    #[must_use]
    pub fn logits(&self, features: &Features) -> Vec<f64> {
        linear(&self.pooled(features), self.weights.head, self.weights.bias)
    }

    /// Noul probabilities from the same pooled state: one pass, several typed
    /// questions. Empty when the bundle has no Noul heads.
    #[must_use]
    pub fn nouls(&self, features: &Features) -> Vec<f64> {
        match (self.weights.noul_head, self.weights.noul_bias) {
            (Some(h), Some(b)) => linear(&self.pooled(features), h, b)
                .into_iter()
                .map(|z| 1.0 / (1.0 + (-z).exp()))
                .collect(),
            _ => Vec::new(),
        }
    }

    /// Featurize, run the forward pass, and read off the decision.
    #[must_use]
    pub fn decide(&self, text: &str) -> Decision {
        let b = self.bundle;
        let prepped = b
            .question_token
            .as_ref()
            .map_or_else(|| text.to_owned(), |q| text.replace('?', &format!(" {q} ")));
        let text = prepped.as_str();
        let features = if b.vocab.is_some() {
            featurize_vocab(text, b.width, |t| b.vocab_row(t))
        } else {
            featurize(text, b.slots.unwrap_or(1), b.width)
        };
        let probs = softmax(&self.logits(&features));
        let nouls = self.nouls(&features);
        let mut order: Vec<usize> = (0..probs.len()).collect();
        order.sort_by(|&a, &b| probs[b].total_cmp(&probs[a]).then(a.cmp(&b)));
        let selected = order[0];
        let second = order.get(1).map_or(0.0, |&i| probs[i]);
        let margin = if probs.len() < 2 {
            1.0
        } else {
            probs[selected] - second
        };
        Decision {
            confidence: probs[selected],
            selected,
            margin,
            probs,
            features,
            nouls,
        }
    }
}

