def u:e2_noul_names() {
  "The three Noul questions asked of every input, in column order.";
  "question|negative|positive"
}

def u:e2_prep(s) {
  "Make a question mark visible to the featurizer, which otherwise treats punctuation as a separator: each one becomes the word qmark.";
  str_join(str_split(s, "?"), " qmark ")
}

def u:e2_render(frame, filler) {
  "Fill a frame's single {} slot; a frame without one is returned as written.";
  str_join(str_split(frame, "{}"), filler)
}

def u:e2_noul_row(tag, filler_tag) {
  "The three Noul labels [question, negative, positive] for one sentence, from its frame's two-character tag and its filler's sentiment.";
  q = str_eq(str_slice(tag, 0, 1), "q");
  sent = str_slice(tag, 1, 1);
  mood = if str_eq(sent, "f") {
    filler_tag
  } else {
    sent
  };
  [q, str_eq(mood, "n"), str_eq(mood, "p")]
}

def u:e2_expand(frames, fillers, tags, filler_tags, c, acc) {
  "Append every frame-filler combination for class c to the running corpus: sentences (newline-joined), class labels, and Noul labels (three per sentence). A frame without a slot contributes one sentence.";
  fs = str_split(fillers, "|");
  ts = str_split(frames, "|");
  gs = str_split(tags, "|");
  ft = if gt(str_len(filler_tags), 0) {
    str_split(filler_tags, "|")
  } else {
    str_split("", "|")
  };
  has_ft = gt(str_len(filler_tags), 0);
  nt = list_len(ts);
  nf = list_len(fs);
  out = acc.lines;
  labels = acc.y;
  nouls = acc.nouls;
  t = 0;
  while lt(t, nt) {
    frame = u:text_lg(ts, t);
    tag = u:text_lg(gs, t);
    reps = if gt(str_find(frame, "{}"), 0 - 1) {
      nf
    } else {
      1
    };
    fi = 0;
    while lt(fi, reps) {
      s = u:e2_render(frame, u:text_lg(fs, fi));
      out = if gt(str_len(out), 0) {
        str_concat(str_concat(out, "\n"), s)
      } else {
        s
      };
      labels = concat(labels, [c]);
      mood = if has_ft {
        u:text_lg(ft, fi)
      } else {
        "0"
      };
      nouls = concat(nouls, u:e2_noul_row(tag, mood));
      fi = fi + 1
    };
    t = t + 1
  };
  {lines: out, y: labels, nouls: nouls}
}

def u:e2_corpus(split) {
  "The generated corpus for a split: 0 for training frames, 1 for held-out validation frames. Returns the sentences as a string list, their class labels, and their Noul labels as an [N, 3] array (question, negative, positive).";
  k = u:e2_count();
  acc = {lines: "", y: fill([0], 0), nouls: fill([0], 0)};
  c = 0;
  while lt(c, k) {
    frames = if eq(split, 0) {
      u:e2_train_frames(c)
    } else {
      u:e2_val_frames(c)
    };
    tags = if eq(split, 0) {
      u:e2_train_tags(c)
    } else {
      u:e2_val_tags(c)
    };
    acc = u:e2_expand(frames, u:e2_fillers(c), tags, u:e2_filler_tags(c), c, acc);
    c = c + 1
  };
  n = reduce_mul(shape(acc.y));
  {texts: str_split(acc.lines, "\n"), y: acc.y, nouls: reshape(acc.nouls, [n, 3])}
}

