//! Featurize demo 01's oracle corpus for model 4. MLPL trains; this only does
//! the bookkeeping the interpreter is slow at over eight thousand rows: the
//! class list, the vocabulary, and the id and mask matrices.
//!
//! - **Classes** are the DOCTOR rules the oracle used. A rule with fewer than
//!   `MIN_RULE` training examples is merged into its keyword's most common
//!   rule, or into `xnone#0` when that keyword has none common enough.
//! - **Vocabulary** is exact: the training split's words and bigrams (after a
//!   question mark becomes `qmark`) seen at least twice, the most frequent
//!   `MAX_VOCAB` of them. Row 0 is reserved for unknown and padding.
//! - **Nouls** are masked. Every row knows whether it is a question: a
//!   generated sentence from its tag, anything else from whether its author
//!   ended it with a question mark. Only generated sentences carry negative
//!   and positive labels; elsewhere those two columns are masked out.
//!
//! usage: `cargo run -p eliza-sim --bin featurize -- CORPUS FRAME_NOULS PROBES PROBE_NOULS SCRIPT OUT`

use std::collections::{BTreeMap, HashMap};

use serde_json::{Value, json};
use tdm_model::{KeywordEngine, KeywordScript, tokens, words};

const WIDTH: usize = 24;
const MIN_RULE: usize = 8;
const MAX_VOCAB: usize = 2000;
const QUESTION_TOKEN: &str = "qmark";
const EXAMPLES: [&str; 10] = [
    "I don't have any problems",
    "my mom never listens to me",
    "are you a computer?",
    "I don't know",
    "i lost my job last week",
    "i got promoted today",
    "everyone hates me",
    "what should i do?",
    "my job is killing me",
    "thank you",
];

struct Row {
    text: String,
    rule: String,
    nouls: [f64; 3],
    mask: [f64; 3],
}

fn prep(text: &str) -> String {
    text.replace('?', &format!(" {QUESTION_TOKEN} "))
}

fn norm(s: &str) -> String {
    words(s).join(" ")
}

fn read(path: &str) -> String {
    std::fs::read_to_string(path).unwrap_or_else(|e| panic!("{path}: {e}"))
}

fn bits(fields: &[&str]) -> [f64; 3] {
    let b = |i: usize| f64::from(u8::from(fields[i] == "1"));
    [b(0), b(1), b(2)]
}

/// Map each used rule to its class: itself when common enough, else its
/// keyword's most common rule, else the catch-all.
fn classes(train: &[Row]) -> (Vec<String>, HashMap<String, usize>) {
    let mut count: BTreeMap<&str, usize> = BTreeMap::new();
    for r in train {
        *count.entry(r.rule.as_str()).or_default() += 1;
    }
    let kept: Vec<String> = count
        .iter()
        .filter(|&(_, &n)| n >= MIN_RULE)
        .map(|(r, _)| (*r).to_owned())
        .collect();
    let index: HashMap<String, usize> = kept
        .iter()
        .enumerate()
        .map(|(i, r)| (r.clone(), i))
        .collect();
    let mut map = index.clone();
    for rule in count.keys() {
        if index.contains_key(*rule) {
            continue;
        }
        let key = rule.split('#').next().unwrap_or_default();
        let target = kept
            .iter()
            .filter(|r| r.split('#').next() == Some(key))
            .max_by_key(|r| (count[r.as_str()], std::cmp::Reverse((*r).clone())))
            .map_or("xnone#0", String::as_str);
        eprintln!("  merged {rule} ({}) into {target}", count[rule]);
        map.insert((*rule).to_owned(), index[target]);
    }
    (kept, map)
}

fn vocabulary(train: &[Row]) -> Vec<String> {
    let mut count: HashMap<String, usize> = HashMap::new();
    for r in train {
        for t in tokens(&prep(&r.text), WIDTH) {
            *count.entry(t).or_default() += 1;
        }
    }
    let mut v: Vec<(String, usize)> = count.into_iter().filter(|&(_, n)| n >= 2).collect();
    v.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    v.truncate(MAX_VOCAB);
    v.into_iter().map(|(t, _)| t).collect()
}

/// Ids and known-masks, [N, WIDTH] each, flattened row-major.
fn matrices(texts: &[&str], index: &HashMap<&str, usize>) -> (Vec<usize>, Vec<u8>) {
    let (mut ids, mut mask) = (Vec::new(), Vec::new());
    for text in texts {
        let toks = tokens(&prep(text), WIDTH);
        for i in 0..WIDTH {
