//! Page state: the bundle, the conversation so far, which turn is selected, and
//! whether the trace is showing.

use std::rc::Rc;

use tdm_model::{Bundle, Conversation, Remembered, Script, ScriptReply, Turn, respond_at};
use yew::prelude::*;

use crate::chat::Chat;
use crate::footer::Footer;
use crate::timeline::Timeline;
use crate::trace::Trace;

/// The trained model and its demo data, embedded at build time so the page is
/// one static download with nothing to fetch.
const BUNDLE: &str = include_str!("../../../fixtures/bundles/demo01-model3.json");

/// The bundle, shared by pointer. Props compare by identity: the bundle never
/// changes after load, and comparing 33,000 weights on every render would be
/// waste.
#[derive(Clone)]
pub struct Shared(pub Rc<Bundle>);

impl PartialEq for Shared {
    fn eq(&self, other: &Self) -> bool {
        Rc::ptr_eq(&self.0, &other.0)
    }
}

impl std::ops::Deref for Shared {
    type Target = Bundle;
    fn deref(&self) -> &Bundle {
        &self.0
    }
}

/// The conversation script: the deterministic half of the demo, as data.
const SCRIPT: &str = include_str!("../../../fixtures/bundles/demo01-script.json");

/// A turn: the model's decision, how long it took in this browser, and what the
/// program did with it -- the reply it built, and what it remembered.
#[derive(Clone)]
pub struct Timed {
    pub turn: Turn,
    pub micros: f64,
    pub reply: ScriptReply,
    pub keywords: Vec<String>,
    /// Memory as it stood when this input arrived.
    pub memory: Vec<Remembered>,
}

fn search() -> String {
    web_sys::window()
        .and_then(|w| w.location().search().ok())
        .unwrap_or_default()
}

/// Inputs requested by `?say=` parameters, replayed at load.
fn initial_inputs() -> Vec<String> {
    crate::query::says(&search())
}

/// Every turn of the conversation, decided by the model at one snapshot. The
/// conversation is stored as inputs, so choosing another point on the training
/// timeline re-decides all of it and the difference is visible turn by turn.
fn decide_all(bundle: &Bundle, snapshot: usize, inputs: &[String]) -> Vec<Timed> {
    let script: Script =
        serde_json::from_str(SCRIPT).expect("the embedded script is validated by the demo tests");
    let mut conversation = Conversation::new(bundle, &script, snapshot);
    inputs
        .iter()
        .enumerate()
        .map(|(i, text)| {
            let memory = conversation.memory().to_vec();
            let micros = time_decision(bundle, snapshot, text, i);
            let x = conversation.say(text);
            Timed {
                turn: x.turn,
                micros,
                reply: x.reply,
                keywords: x.keywords,
                memory,
            }
        })
        .collect()
}

/// Browsers coarsen `performance.now()` (to 100 us without cross-origin
/// isolation), which is slower than one decision. So each decision is timed over
/// this many repetitions and the mean is reported.
const TIMING_RUNS: u32 = 100;

/// Mean microseconds for the model's decision on one input.
fn time_decision(bundle: &Bundle, snapshot: usize, text: &str, index: usize) -> f64 {
    let start = now_ms();
    for _ in 0..TIMING_RUNS {
        let _ = respond_at(bundle, snapshot, text, index);
    }
    (now_ms() - start) * 1000.0 / f64::from(TIMING_RUNS)
}

fn now_ms() -> f64 {
    web_sys::window()
        .and_then(|w| w.performance())
        .map_or(0.0, |p| p.now())
}

#[derive(Properties, PartialEq)]
struct HeaderProps {
    demo: String,
            e.min_margin,
            e.min_known,
            if e.min_known == 1 { "" } else { "s" },
            bundle.labels.len(),
            bundle.labels[r.label]
        ),
        (Outcome::Escalate, None) => format!(
            "confidence {:.3} < {:.2}  →  abstain, fall back to {}",
            d.confidence, bundle.threshold, bundle.labels[r.label]
        ),
    };
    html! { <p class={classes!("mono", (r.outcome == Outcome::Escalate).then_some("escalate"))}>{ text }</p> }
}

fn describe(by: &Move) -> String {
    match by {
        Move::Recall { turn, keyword } => format!(
            "repeat rule: \"{keyword}\" was used before, in turn {}, which is brought back",
            turn + 1
        ),
        Move::Memory { turn } => format!(
            "memory rule: nothing else fit, so a remembered statement from turn {} comes back",
            turn + 1
        ),
        Move::LabelRule { label, rule } => format!("{label} rule: {rule}"),
        Move::KeywordRule { rule } => format!("keyword rule for any label: {rule}"),
        Move::Reflect => {
            "reflection: nothing matched, so the visitor's own words come back".to_owned()
        }
        Move::Canned => "the chosen label's canned reply".to_owned(),
        Move::Deflect { noul, p } => format!(
            "deflection: the {noul} Noul said {p:.2}, and questions are turned back, not answered"
        ),
        Move::Sentiment { noul, p } => {
            format!("sentiment reflection: nothing fit the label, and the {noul} Noul said {p:.2}")
        }
    }
}

fn built(t: &Timed) -> Html {
    let r = &t.reply;
    let slots = r
        .slots
        .iter()
        .map(|(n, v)| format!("{{{n}}} = \"{v}\""))
        .collect::<Vec<_>>()
        .join(",  ");
    html! {
        <>
            <p class="mono">{ describe(&r.by) }</p>
            <p class="mono">{ format!("frame: \"{}\"", r.frame) }</p>
            if !slots.is_empty() {
                <p class="mono">{ format!("slots: {slots}  — the visitor's own words, pronouns reflected") }</p>
            }
            <p class="meta">{ "The reply is exactly the frame with the slots filled. Nothing is generated." }</p>
        </>
    }
}

fn memory(t: &Timed) -> Html {
    let recalled = match t.reply.by {
