input.content:
# A question-conditioned scorer over choices supplied as text, not as head columns: score_i = f(h_state, h_question, h_card_i). One shared text encoder reads the state, the question and every candidate card; the state and question are combined into one query vector and scored against each card by inner product. Because a card enters through the encoder rather than through a column of a fixed head, the same weights score cards that did not exist when training ended -- which is the whole point, and what a fixed-head Choice cannot do. Domain-neutral: a card is text, a question is text, and what they mean is the caller's business. Training runs over the caller's global params sc_E [rows, d], sc_Ws [d, d], sc_Wq [d, d] and sc_Wc [d, d]; inference runs over a plain weights record, and tests/test_scorer.mlpl asserts the two forward passes agree.

include "text.mlpl";

def u:sc_pooled(ids, wmask) {
  "Mean-pooled rows of the caller's global embedding for a featurized batch: [N, d]. The caller supplies the pooling weights, so feature width and pooling are its choice, not this library's.";
  reduce_add(gather_rows(sc_E, ids) * wmask, 1)
}

def u:sc_query(s, q, qi) {
  "The query vector [N, d]: the state and its question encoded by the same embedding and combined through their own weights. tanh keeps the query bounded, so a long card cannot win on magnitude alone.";
  hs = u:sc_pooled(s.ids, s.wmask);
  hq = gather_rows(u:sc_pooled(q.ids, q.wmask), qi);
  tanh(matmul(hs, sc_Ws) + matmul(hq, sc_Wq))
}

def u:sc_cards(c) {
  "Every candidate card encoded once, [K, d]. Cards are scored, not enumerated in a head, so this may be called with cards the model never trained on.";
  matmul(u:sc_pooled(c.ids, c.wmask), sc_Wc)
}

def u:sc_mask(scores, cand) {
  "Scores [N, K] with the cards a row was not offered pushed far below every offered one, so one softmax can cover a different choice set per row.";
  scores + (cand - 1) * 1000
}

def u:sc_logits(s, q, c, qi, cand) {
  "Scores [N, K] of every offered card for every row: the query against each encoded card.";
  u:sc_mask(matmul(u:sc_query(s, q, qi), transpose(u:sc_cards(c))), cand)
}

def u:sc_loss(s, q, c, qi, cand, y) {
  "Cross-entropy of the offered cards against the answer's card index.";
  cross_entropy(u:sc_logits(s, q, c, qi, cand), y)
}

def u:sc_train(s, q, c, qi, cand, y, steps, lr) {
  "Adam over the shared encoder and the three projections; returns the final loss. Adam's moments persist between calls in one process, so calling this once per minibatch continues one optimization.";
  train steps {
    adam(u:sc_loss(s, q, c, qi, cand, y), [sc_E, sc_Ws, sc_Wq, sc_Wc], lr, 0.9, 0.999, 0.00000001)
  };
  u:sc_loss(s, q, c, qi, cand, y)
}

def u:sc_infer(w, s, q, c, qi, cand) {
  "The same scores from a plain weights record, the inference half of u:sc_logits. A trained scorer is four arrays; this is all a consumer needs to run it.";
  hs = reduce_add(gather_rows(w.E, s.ids) * s.wmask, 1);
  hq = gather_rows(reduce_add(gather_rows(w.E, q.ids) * q.wmask, 1), qi);
  u = tanh(matmul(hs, w.Ws) + matmul(hq, w.Wq));
  hc = matmul(reduce_add(gather_rows(w.E, c.ids) * c.wmask, 1), w.Wc);
  u:sc_mask(matmul(u, transpose(hc)), cand)
}

def u:sc_choose(w, s, q, c, qi, cand) {
  "The selected card per row and the probability the scorer gave it, as a record: {selected [N], probs [N, K]}.";
  p = softmax(u:sc_infer(w, s, q, c, qi, cand), 1);
  {selected: argmax(p, 1), probs: p}
}

def u:sc_param_count(w) {
  "How many learned numbers a scorer is: the shared embedding plus the three projections. It does not grow when a card is added, which is the difference this lesson exists to measure.";
  reduce_mul(shape(w.E)) + reduce_mul(shape(w.Ws)) + reduce_mul(shape(w.Wq)) + reduce_mul(shape(w.Wc))
}

