        .into_iter()
        .filter(|(t, n)| *n >= 2 && !named.contains(t))
        .collect();
    rest.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    rest.truncate(MAX_VOCAB.saturating_sub(named.len()));
