        "width": WIDTH,
        "card_width": CARD_WIDTH,
        "rule_count": rule_count,
        "held_out": HELD_OUT,
        "cards": {
            "names": cards.iter().map(|c| c.name.clone()).collect::<Vec<_>>(),
            "texts": card_texts,
            "ids": cids,
            "mask": cmask,
        },
