attachment.snippet:
1	# A question-conditioned scorer over choices supplied as text, not as head columns: score_i = f(h_state, h_question, h_card_i). One shared text encoder reads the state, the question and every candidate card; the state and question become one query vector, which is scored against each card by inner product. Because a card enters through the encoder rather than through a column of a fixed head, the same weights score cards that did not exist when training ended -- which is the point, and what a fixed-head Choice cannot do. Domain-neutral: a card is text, a question is text, and what they mean is the caller's business; the caller also chooses the feature width and the pooling, since it supplies the ids and the pooling weights. Training runs over the caller's global params sc_E [rows, d], sc_Ws [d, d], sc_Wq [d, d], sc_Wc [d, d] and the scalar sc_g; inference runs over a plain weights record, and tests/test_scorer.mlpl asserts the two forward passes agree. Every differentiated entry point takes plain arrays, never a record: a record field read inside grad is not a supported expression form (probes/q5_record_field_in_grad.mlpl).
2	
3	include "text.mlpl";
4	
5	def u:sc_pooled(ids, wmask) {
6	  "Mean-pooled rows of the caller's global embedding for a featurized batch: [N, d].";
7	  reduce_add(gather_rows(sc_E, ids) * wmask, 1)
8	}
9	
10	def u:sc_query(sids, swm, qids, qwm, qi) {
11	  "The query vector [N, d]: the state and its question encoded by the same embedding and combined through their own weights. qi [N] names each row's question, so one batch may mix questions. tanh keeps the query bounded, so a long card cannot win on magnitude alone.";
12	  hs = u:sc_pooled(sids, swm);
13	  hq = gather_rows(u:sc_pooled(qids, qwm), qi);
14	  tanh(matmul(hs, sc_Ws) + matmul(hq, sc_Wq))
15	}
16	
17	def u:sc_unit(a) {
18	  "Rows of [K, d] scaled to unit length; a row of zeros is left alone. Measured, not assumed: scoring by plain inner product gives a card that trained as an answer a magnitude no unseen card can match, and unseen cards then never win. Direction is what a card should be compared on.";
19	  n = sqrt(reduce_add(a * a, 1));
20	  a / reshape(n + eq(n, 0), [take(shape(a), 0, 0), 1])
21	}
22	
23	def u:sc_cards(cids, cwm) {
24	  "Every candidate card encoded once and scaled to unit length, [K, d]. Cards are scored, not enumerated in a head, so this may be called with cards the model never trained on.";
25	  u:sc_unit(matmul(u:sc_pooled(cids, cwm), sc_Wc))
26	}
27	
28	def u:sc_mask(scores, cand) {
29	  "Scores [N, K] with the cards a row was not offered pushed far below every offered one, so one softmax covers a choice set that differs from row to row.";
30	  scores + (cand - 1) * 1000
31	}
32	
33	def u:sc_logits(sids, swm, qids, qwm, qi, cids, cwm, cand) {
34	  "Scores [N, K] of every offered card for every row: the query against each unit card, times the learned scale sc_g, which is what lets a cosine reach a confident probability.";
35	  u:sc_mask(sc_g * matmul(u:sc_query(sids, swm, qids, qwm, qi), transpose(u:sc_cards(cids, cwm))), cand)
36	}
37	
38	def u:sc_loss(sids, swm, qids, qwm, qi, cids, cwm, cand, y) {
39	  "Cross-entropy of the offered cards against the answer's card index.";
40	  cross_entropy(u:sc_logits(sids, swm, qids, qwm, qi, cids, cwm, cand), y)
41	}
42	
43	def u:sc_train(sids, swm, qids, qwm, qi, cids, cwm, cand, y, steps, lr) {
44	  "Adam over the shared encoder and the three projections; returns the final loss. Adam's moments persist between calls in one process, so calling this once per minibatch continues one optimization.";
45	  train steps {
46	    adam(u:sc_loss(sids, swm, qids, qwm, qi, cids, cwm, cand, y), [sc_E, sc_Ws, sc_Wq, sc_Wc, sc_g], lr, 0.9, 0.999, 0.00000001)
47	  };
48	  u:sc_loss(sids, swm, qids, qwm, qi, cids, cwm, cand, y)
49	}
50	
51	def u:sc_infer(w, sids, swm, qids, qwm, qi, cids, cwm, cand) {
52	  "The same scores from a plain weights record, the inference half of u:sc_logits. A trained scorer is four arrays; this is all a consumer needs to run it.";
53	  hs = reduce_add(gather_rows(w.E, sids) * swm, 1);
54	  hq = gather_rows(reduce_add(gather_rows(w.E, qids) * qwm, 1), qi);
55	  u = tanh(matmul(hs, w.Ws) + matmul(hq, w.Wq));
56	  hc = u:sc_unit(matmul(reduce_add(gather_rows(w.E, cids) * cwm, 1), w.Wc));
57	  u:sc_mask(w.g * matmul(u, transpose(hc)), cand)
58	}
59	
60	def u:sc_choose(w, sids, swm, qids, qwm, qi, cids, cwm, cand) {
61	  "The selected card per row and the full distribution over the offered cards: {selected [N], probs [N, K]}.";
62	  p = softmax(u:sc_infer(w, sids, swm, qids, qwm, qi, cids, cwm, cand), 1);
63	  {selected: argmax(p, 1), probs: p}
64	}
65	
66	def u:sc_param_count(w) {
67	  "How many learned numbers a scorer is: the shared embedding plus the three projections. It does not grow when a card is added, which is the difference this lesson exists to measure.";
68	  reduce_mul(shape(w.E)) + reduce_mul(shape(w.Ws)) + reduce_mul(shape(w.Wq)) + reduce_mul(shape(w.Wc)) + 1
69	}

