# Demo 01's Choice model, trained from random weights in the browser. This is the program the live demo hands you to run in sw-MLPL's own hosted Live Editor: paste it or Load it, press Run, and watch a model that starts at chance learn to pick a reply class -- the same library, the same corpus and the same optimizer the committed model was trained with, only smaller so an interpreter in WASM can finish it while you watch. Browser-safe by construction: no file IO, no clock, no arguments, and scripts/bundle-program proves it by walking the call graph before flattening the include tree into one file. The configuration is smaller than the shipped model's (256 slots, 16 dimensions, 60 steps against 1024, 32, 200), because what has to be visible here is the shape of learning, not a state of the art.
include "../../lib/choice_model.mlpl";
include "eliza.mlpl";

bz_slots = 256;
bz_width = 24;
bz_dim = 16;
bz_lr = 0.08;
bz_stages = [0, 5, 15, 30, 60];

def u:bz_accuracy(weights, fz, y) {
  "Share of rows whose highest-scoring class is the labelled one.";
  mean(eq(argmax(u:cm_infer(weights, fz.ids, fz.wmask), 1), y))
}

def u:bz_confidence(weights, fz) {
  "Mean probability the model gives its own pick -- how sure it is, which is a different question from whether it is right.";
  mean(reduce(:max, softmax(u:cm_infer(weights, fz.ids, fz.wmask), 1), 1))
}

def u:bz_weights() {
  "The globals as the plain record inference takes.";
  {E: cm_E, W: cm_W, b: cm_b, labels: u:ez_labels(), slots: bz_slots, width: bz_width}
}

